import { computed } from 'vue';
import type { AriaAttributes } from 'vue';

// Vue透传的标准ARIA与本预览专用DOM事件；不放宽未知业务属性或事件。
declare module 'vue' {
	interface ComponentCustomProps {
		'aria-label'?: string;
		'aria-current'?: AriaAttributes['aria-current'];
	}
	interface HTMLAttributes {
		onAsamPreviewTheme?: (event: CustomEvent<'light' | 'dark'>) => void;
	}
}

/** 公共输入允许清空或多种标量，页面模型只接收自己声明的合法值。 */
export function choiceModel<Value extends string | number>(
	read: () => Value,
	write: (value: Value) => void,
	choices: readonly Value[]
) {
	return computed({
		get: read,
		set(value: unknown) {
			if (choices.some((choice) => Object.is(choice, value))) write(value as Value);
		}
	});
}
export function booleanModel(read: () => boolean, write: (value: boolean) => void) {
	return computed({
		get: read,
		set(value: unknown) {
			if (typeof value === 'boolean') write(value);
		}
	});
}
export function textModel(read: () => string, write: (value: string) => void) {
	return computed({
		get: read,
		set(value: unknown) {
			if (typeof value === 'string') write(value);
		}
	});
}

import type { AsamCardLayout, AsamCardSize } from '@asam-ui/ui';

/** 模板展示配置；仅透传公开几何属性，不保存业务数据或控件 size。 */
export interface CardPresentation {
	readonly layout: AsamCardLayout;
	readonly cardSize: AsamCardSize;
	readonly columns: 'auto' | number;
	readonly maxWidth?: number;
}

export const createCardPresentation = (cardSize: AsamCardSize = 'default'): CardPresentation => ({
	layout: 'grid',
	cardSize,
	columns: 'auto'
});

const en = {
	layout: 'Layout',
	grid: 'Grid',
	masonry: 'Masonry',
	cardSize: 'Card density',
	small: 'Small',
	default: 'Default',
	big: 'Big',
	large: 'Large',
	custom: 'Custom',
	minWidth: 'Minimum width',
	columns: 'Columns',
	auto: 'Auto',
	maxWidth: 'Maximum width',
	unlimited: 'Unlimited'
};
const zh = {
	layout: '布局',
	grid: '网格',
	masonry: '瀑布流',
	cardSize: '卡片密度',
	small: '紧凑',
	default: '默认',
	big: '宽松',
	large: '大卡片',
	custom: '自定义',
	minWidth: '最小宽度',
	columns: '列数',
	auto: '自动',
	maxWidth: '最大宽度',
	unlimited: '不限制'
};
export type CardGeometryLabel = keyof typeof en;
type CardGeometryParameters = {
	[K in CardGeometryLabel as `app.templates.cards.${K}`]: Record<never, never>;
};
declare module '@asam-ui/ui/i18n' {
	interface AsamI18nMessageParameters extends CardGeometryParameters {}
}
const prefix = (values: typeof en) =>
	Object.fromEntries(
		Object.entries(values).map(([key, value]) => ['app.templates.cards.' + key, value])
	) as { [K in keyof CardGeometryParameters]: string };
export const cardGeometryMessages = { en: prefix(en), 'zh-CN': prefix(zh) };

import type { AsamI18n } from '@asam-ui/ui/i18n';
import type {} from './i18n/Parameters.js';
import type { ChartSeries } from './Types.js';
/** Validate before invoking the engine. Null is a gap, zero and signed decimals are values. */
export function validateSeries(
	series: readonly ChartSeries[],
	scope?: AsamI18n
): string | undefined {
	const ids = new Set<string>();
	for (const item of series) {
		if (!item.id || ids.has(item.id))
			return scope?.enabled.value
				? scope.t('app.templates.visualization.seriesId')
				: 'series ID 缺失或重复';
		ids.add(item.id);
		if (!['line', 'bar', 'pie'].includes(item.kind))
			return scope?.enabled.value
				? scope.t('app.templates.visualization.chartKind')
				: '未注册的图表类型';
		const points = new Set<string>();
		for (const point of item.points) {
			if (!point.id || points.has(point.id))
				return scope?.enabled.value
					? scope.t('app.templates.visualization.pointId')
					: 'point ID 缺失或重复';
			points.add(point.id);
			if (point.value !== null && !Number.isFinite(point.value))
				return scope?.enabled.value
					? scope.t('app.templates.visualization.finite')
					: '图表值必须为有限数字或 null';
			if (item.kind === 'pie' && point.value !== null && point.value < 0)
				return scope?.enabled.value
					? scope.t('app.templates.visualization.negativePie')
					: '饼图不支持负数；请使用折线或柱图';
		}
	}
}

import { init, use } from 'echarts/core';
import { LineChart, BarChart, PieChart } from 'echarts/charts';
import {
	GridComponent,
	TooltipComponent,
	LegendComponent,
	DataZoomComponent,
	AriaComponent
} from 'echarts/components';
import { SVGRenderer } from 'echarts/renderers';
use([
	LineChart,
	BarChart,
	PieChart,
	GridComponent,
	TooltipComponent,
	LegendComponent,
	DataZoomComponent,
	AriaComponent,
	SVGRenderer
]);
export { init };

import type * as ChartEngine from './Engine.js';
/** Vite resolves this marker to its own emitted entry, including the configured base URL.
 * A fresh URL on retry avoids the browser's cached rejected dynamic-import promise.
 * No remote scripts, copied engine code or alternate dependency instance are used.
 */
let loaded: typeof ChartEngine | undefined;
export async function loadEngine(attempt: number): Promise<typeof ChartEngine> {
	if (loaded) return loaded;
	const url = new URL('__ASAM_ENGINE_URL__', import.meta.url);
	if (attempt > 0) url.searchParams.set('asam-retry', String(attempt));
	const engine: typeof ChartEngine = await import(/* @vite-ignore */ url.href);
	loaded = engine;
	return engine;
}

import { createAsamMessageError } from '@asam-ui/pro/i18n';
import type {} from './i18n/Parameters.js';
import type {
	MonitorOptions,
	MonitorSource,
	MonitorSnapshot,
	StreamPoint,
	Subscription,
	ConnectionState
} from './Types.js';
function bounded(value: number | undefined, fallback: number, min: number, max: number) {
	return value === undefined
		? fallback
		: Number.isFinite(value)
			? Math.min(max, Math.max(min, Math.trunc(value)))
			: fallback;
}
/** One controller per mounted page. No global pool, background wakeup or unbounded queue. */
export function createMonitor(
	options: MonitorOptions,
	changed: (snapshot: MonitorSnapshot) => void
) {
	if (!options.streams.length || new Set(options.streams).size !== options.streams.length)
		throw createAsamMessageError(
			new TypeError('唯一流 ID 必填'),
			'app.templates.visualization.streamRequired'
		);
	const capacity = bounded(options.capacity, 600, 1, 600);
	const interval = bounded(options.intervalMs, 100, 50, 60_000);
	const batch = bounded(options.batchMs, 100, 100, 10_000);
	const retries = bounded(options.reconnects, 3, 0, 10);
	const backoff = bounded(options.backoffMs, 1000, 100, 10_000);
	let state: ConnectionState = 'idle';
	let source: MonitorSource | undefined;
	let subscription: Subscription | undefined;
	let request: AbortController | undefined;
	let generation = 0;
	let attempts = 0;
	let dropped = 0;
	let lastAt: number | null = null;
	let receivedAt = 0;
	let startedAt = 0;
	let destroyed = false;
	const timers = new Set<ReturnType<typeof setTimeout>>();
	const points: Record<string, StreamPoint[]> = Object.fromEntries(
		options.streams.map((id) => [id, []])
	);
	const pending: Record<string, StreamPoint[]> = Object.fromEntries(
		options.streams.map((id) => [id, []])
	);
	const sequences = new Map<string, number>();
	let flushing = false;
	function snapshot(): MonitorSnapshot {
		return {
			state,
			source: source?.id ?? '',
			attempts,
			dropped,
			lastAt,
			points: Object.fromEntries(options.streams.map((id) => [id, points[id]!.slice()]))
		};
	}
	function publish() {
		if (!destroyed) changed(snapshot());
	}
	function schedule(fn: () => void, delay: number, token: number) {
		const timer = setTimeout(() => {
			timers.delete(timer);
			if (!destroyed && token === generation) fn();
		}, delay);
		timers.add(timer);
	}
	function cleanup() {
		++generation;
		for (const timer of timers) clearTimeout(timer);
		timers.clear();
		flushing = false;
		const old = subscription;
		subscription = undefined;
		old?.close();
		const oldRequest = request;
		request = undefined;
		oldRequest?.abort();
		for (const id of options.streams) {
			dropped += pending[id]!.length;
			pending[id] = [];
		}
	}
	function accept(point: StreamPoint, token: number) {
		if (token !== generation || destroyed) return;
		if (typeof point !== 'object' || point === null) {
			dropped++;
			return;
		}
		if (
			!Object.hasOwn(points, point.stream) ||
			!Number.isSafeInteger(point.seq) ||
			point.seq < 0 ||
			!Number.isFinite(point.at) ||
			(point.value !== null && !Number.isFinite(point.value))
		) {
			dropped++;
			return;
		}
		if (point.seq <= (sequences.get(point.stream) ?? -1)) {
			dropped++;
			return;
		}
		sequences.set(point.stream, point.seq);
		const queue = pending[point.stream]!;
		queue.push({ ...point });
		if (queue.length > capacity) {
			queue.shift();
			dropped++;
		}
		receivedAt = Date.now();
		lastAt = point.at;
		state = 'live';
		if (!flushing) {
			flushing = true;
			schedule(
				() => {
					flushing = false;
					for (const id of options.streams) {
						const all = [...points[id]!, ...pending[id]!];
						dropped += Math.max(0, all.length - capacity);
						points[id] = all.slice(-capacity);
						pending[id] = [];
					}
					publish();
				},
				batch,
				token
			);
		}
	}
	function staleWatch(token: number) {
		schedule(
			() => {
				if (
					['connecting', 'live', 'stale'].includes(state) &&
					Date.now() - (receivedAt || startedAt) > interval * 3
				) {
					state = 'stale';
					publish();
				}
				staleWatch(token);
			},
			interval,
			token
		);
	}
	function connect(isRetry = false) {
		if (!source || destroyed) return;
		cleanup();
		sequences.clear();
		receivedAt = 0;
		startedAt = Date.now();
		for (const id of options.streams) points[id] = [];
		const token = generation;
		state = isRetry ? 'reconnecting' : 'connecting';
		publish();
		staleWatch(token);
		if ('subscribe' in source) {
			let failed = false;
			const fail = () => {
				if (token !== generation || failed || destroyed) return;
				failed = true;
				cleanup();
				if (attempts >= retries) {
					state = 'error';
					publish();
					return;
				}
				const delay = Math.min(10_000, backoff * 2 ** attempts++);
				state = 'reconnecting';
				publish();
				schedule(() => connect(true), delay, generation);
			};
			try {
				const created = source.subscribe({
					open() {
						if (token === generation && !failed) {
							state = 'live';
							publish();
						}
					},
					message: (p) => accept(p, token),
					error: fail
				});
				if (token === generation && !failed) subscription = created;
				else created.close();
			} catch {
				fail();
			}
		} else {
			const pollSource = source;
			async function poll() {
				const controller = new AbortController();
				request = controller;
				try {
					const data = await pollSource.poll(controller.signal);
					if (token !== generation) return;
					data.forEach((p) => accept(p, token));
				} catch {
					if (token === generation && !controller.signal.aborted) {
						state = 'error';
						publish();
					}
				} finally {
					if (request === controller) request = undefined;
					if (token === generation && !destroyed)
						schedule(() => void poll(), interval, token);
				}
			}
			void poll();
		}
	}
	return {
		start(next: MonitorSource) {
			if (destroyed) return;
			cleanup();
			source = next;
			attempts = 0;
			lastAt = null;
			for (const id of options.streams) points[id] = [];
			connect();
		},
		pause() {
			if (destroyed) return;
			cleanup();
			state = 'paused';
			publish();
		},
		resume() {
			if (!destroyed && state === 'paused') {
				attempts = 0;
				connect();
			}
		},
		reconnect() {
			if (!destroyed) {
				attempts = 0;
				connect();
			}
		},
		close() {
			if (destroyed) return;
			cleanup();
			state = 'closed';
			publish();
		},
		dispose() {
			cleanup();
			state = 'closed';
			destroyed = true;
		},
		snapshot,
		resources: () => ({
			timers: timers.size,
			subscription: !!subscription,
			request: !!request,
			pending: Object.values(pending).reduce((n, p) => n + p.length, 0)
		})
	};
}

import { createAsamMessageError } from '@asam-ui/pro/i18n';
import type {} from './i18n/Parameters.js';
import { createRequestClient, TransportFault } from '@asam-ui/pro/application/transport';
import type {
	AnalyticsData,
	AnalyticsFilter,
	PollSource,
	StreamPoint,
	SubscribeSource
} from './Types.js';
import type { RequestClient } from '@asam-ui/pro/application/transport';
export interface AnalyticsService {
	readonly client: RequestClient;
	load(filter: AnalyticsFilter, signal: AbortSignal): Promise<AnalyticsData>;
}
export function decodeAnalytics(data: unknown): AnalyticsData {
	if (
		typeof data !== 'object' ||
		!data ||
		!('points' in data) ||
		!Array.isArray(data.points) ||
		!('total' in data) ||
		typeof data.total !== 'number' ||
		!Number.isFinite(data.total) ||
		!('partial' in data) ||
		typeof data.partial !== 'boolean'
	)
		throw createAsamMessageError(
			new TypeError('无效分析响应'),
			'app.templates.visualization.invalidResponse'
		);
	const ids = new Set<string>();
	const points = data.points.map((p: unknown) => {
		if (
			typeof p !== 'object' ||
			!p ||
			!('id' in p) ||
			typeof p.id !== 'string' ||
			ids.has(p.id) ||
			!('label' in p) ||
			typeof p.label !== 'string' ||
			!('value' in p) ||
			(p.value !== null && (typeof p.value !== 'number' || !Number.isFinite(p.value)))
		)
			throw createAsamMessageError(
				new TypeError('无效分析点'),
				'app.templates.visualization.invalidPoint'
			);
		ids.add(p.id);
		return { id: p.id, label: p.label, value: p.value };
	});
	return { points, total: data.total, partial: data.partial };
}
/** Replace this local deterministic transport at application composition; no CL backend implied. */
export function createLocalAnalyticsService(): AnalyticsService {
	const client = createRequestClient({
		transport: async (input, context) => {
			const filter = input.params as unknown as AnalyticsFilter;
			await new Promise<void>((resolve, reject) => {
				const timer = setTimeout(resolve, filter.delayMs ?? 70);
				context.signal.addEventListener(
					'abort',
					() => {
						clearTimeout(timer);
						reject(new TransportFault('cancelled'));
					},
					{ once: true }
				);
			});
			if (filter.mode === 'error') throw new TransportFault('network');
			const length =
				filter.mode === 'empty'
					? 0
					: filter.mode === 'partial'
						? Math.floor(filter.range / 2)
						: filter.range;
			const multiplier =
				filter.category === 'north' ? 1.4 : filter.category === 'south' ? 0.7 : 1;
			const points = Array.from({ length }, (_, i) => ({
				id: String(i),
				label: `时段 ${i + 1}`,
				value:
					i % 97 === 0
						? null
						: Math.round((40 + Math.sin(i / 17) * 15 + (i % 13)) * multiplier * 100) /
							100
			}));
			return {
				mode: 'data',
				data: {
					points,
					total: points.reduce((n, p) => n + (p.value ?? 0), 0),
					partial: filter.mode === 'partial'
				}
			};
		}
	});
	return {
		client,
		load: (filter, signal) =>
			client.request(
				{ url: 'local:analytics', params: { ...filter } },
				{ signal, decode: decodeAnalytics }
			)
	};
}
export function createSseSource(url: string, id = '本地 SSE'): SubscribeSource {
	return {
		id,
		subscribe(sink) {
			const event = new EventSource(url);
			event.onopen = () => sink.open();
			event.onmessage = (e) => {
				try {
					sink.message(JSON.parse(e.data) as StreamPoint);
				} catch {
					event.close();
					sink.error();
				}
			};
			event.onerror = () => {
				event.close();
				sink.error();
			};
			return {
				close() {
					event.onopen = null;
					event.onmessage = null;
					event.onerror = null;
					event.close();
				}
			};
		}
	};
}
export function createPollingSource(
	client: RequestClient,
	url: string,
	id = '本地 polling'
): PollSource {
	return {
		id,
		poll: (signal) =>
			client.request(
				{ url },
				{
					signal,
					decode(data) {
						if (!Array.isArray(data))
							throw createAsamMessageError(
								new TypeError('无效轮询响应'),
								'app.templates.visualization.invalidPolling'
							);
						return data as StreamPoint[];
					}
				}
			)
	};
}

.viz-shell {
	--viz-bg: var(--asam-color-surface-muted, #f3f6f7);
	--viz-surface: var(--asam-color-surface, #fff);
	--viz-text: var(--asam-color-text-primary, #20363e);
	--viz-border: var(--asam-color-border, #d8e1e5);
	--viz-control: 32px;
	background: var(--viz-bg);
	color: var(--viz-text);
	min-height: 100%;
	font: 14px/1.5 var(--asam-typography-font-family, 'Segoe UI', sans-serif);
}
.viz-shell.dark {
	color-scheme: dark;
}
.viz-shell[data-size='large'] {
	--viz-control: 40px;
}
.viz-shell[data-size='big'] {
	--viz-control: 36px;
}
.viz-shell[data-size='small'] {
	--viz-control: 28px;
}
body {
	margin: 0;
}
.viz-shell * {
	box-sizing: border-box;
}
.viz-shell nav {
	display: flex;
	align-items: center;
	gap: 16px;
	padding: 16px 3vw;
	border-bottom: 1px solid var(--viz-border);
	background: var(--viz-surface);
	flex-wrap: wrap;
}
.viz-shell nav strong {
	margin-right: auto;
	letter-spacing: 0.12em;
}
.viz-shell small {
	font-size: 10px;
	font-weight: 400;
}
.viz-shell button:not([class*='el-']),
.viz-shell input:not([class*='el-']),
.viz-shell select:not([class*='el-']) {
	font: inherit;
	color: inherit;
	background: var(--viz-surface);
	border: 1px solid var(--viz-border);
	border-radius: var(--asam-radius-control, 4px);
	min-height: var(--viz-control);
	line-height: 20px;
	padding: 3px 10px;
}
.viz-shell button:not([class*='el-']) {
	cursor: pointer;
}
.viz-shell button:not([class*='el-']):hover,
.viz-shell [aria-current='page']:not(.el-button) {
	border-color: var(--asam-semantic-primary-foreground);
	color: var(--asam-semantic-primary-foreground);
}
.viz-shell :focus-visible {
	outline: 3px solid var(--asam-semantic-focus);
	outline-offset: 3px;
}
.viz-shell input:not([class*='el-'])[type='checkbox'] {
	min-height: 0;
}
.viz-page {
	max-width: 1600px;
	margin: auto;
	padding: 28px 3vw;
}
.viz-heading {
	display: flex;
	justify-content: space-between;
	align-items: center;
	gap: 16px;
	margin-bottom: 22px;
}
.viz-heading h1 {
	font-size: 32px;
	letter-spacing: -0.035em;
	margin: 4px 0;
}
.viz-heading p {
	margin: 0;
	color: var(--asam-color-text-secondary, #657983);
}
.viz-eyebrow {
	font-size: 11px;
	letter-spacing: 0.12em;
}
.viz-toolbar {
	display: flex;
	align-items: end;
	gap: 12px;
	flex-wrap: wrap;
	margin-bottom: 16px;
}
.viz-toolbar label {
	display: grid;
	gap: 4px;
	font-size: 12px;
}
.viz-shell nav label {
	display: flex;
	align-items: center;
	gap: 5px;
}
.viz-analysis-grid {
	display: grid;
	grid-template-columns: 1.4fr 1fr;
	gap: 18px;
	margin-top: 24px;
}
.viz-analysis-grid > .viz-chart:first-child {
	grid-column: 1/-1;
}
.viz-monitor-grid {
	display: grid;
	grid-template-columns: repeat(3, minmax(0, 1fr));
	gap: 16px;
	margin-top: 24px;
}
.viz-chart {
	min-width: 0;
	padding: 18px;
	background: var(--viz-surface);
	border: 1px solid var(--viz-border);
	border-radius: var(--asam-radius-card, 8px);
}
.viz-chart header {
	display: flex;
	justify-content: space-between;
}
.viz-chart h2 {
	font-size: 15px;
	margin: 0 0 12px;
}
.viz-chart .asam-form-section {
	border: 0;
	padding: 0;
	display: flex;
	gap: 12px;
	font-size: 12px;
}
.viz-chart .asam-form-section-title {
	font-size: 11px;
	color: var(--asam-color-text-secondary, #657983);
}
.viz-plot {
	width: 100%;
}
.viz-chart summary {
	cursor: pointer;
	font-size: 12px;
	margin-top: 12px;
}
.viz-table {
	max-height: 260px;
	overflow: auto;
}
.viz-table table {
	border-collapse: collapse;
	width: 100%;
	font-size: 12px;
}
.viz-table th,
.viz-table td {
	text-align: left;
	padding: 6px;
	border-bottom: 1px solid var(--viz-border);
}
.viz-status {
	border: 1px solid var(--viz-border);
	padding: 6px 12px;
